public with sharing class ContactTriggerHandler {

    public void beforeInsert(List<Contact> newContacts) {
        populateAccountDefaults(newContacts, true);
    }

    public void beforeUpdate(List<Contact> newContacts) {
        populateAccountDefaults(newContacts, false);
    }

    public void afterInsert(List<Contact> newContacts) {
        Map<Id, String> accountIdToPhone = new Map<Id, String>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone) && !accountIdToPhone.containsKey(c.AccountId)) {
                accountIdToPhone.put(c.AccountId, c.Phone);
            }
        }

        if (accountIdToPhone.isEmpty()) {
            return;
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account a : [SELECT Id, Phone FROM Account WHERE Id IN :accountIdToPhone.keySet()]) {
            if (String.isBlank(a.Phone)) {
                a.Phone = accountIdToPhone.get(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private void populateAccountDefaults(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                if (String.isBlank(c.MailingCountry) || (isInsert && String.isBlank(c.LeadSource))) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : contacts) {
            if (c.AccountId != null) {
                Account a = accountMap.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    if (isInsert && String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }
}
