public with sharing class RecordSearchService {
    public class SearchException extends Exception {}

    @AuraEnabled(cacheable=true)
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API name must not be blank.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list must not be null or empty.');
            }
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            List<Schema.DescribeSObjectResult> describes;
            try {
                describes = Schema.describeSObjects(new List<String>{ objectApiName.trim() });
            } catch (Exception e) {
                throw new SearchException('Invalid or non-existent object: ' + objectApiName, e);
            }

            if (describes == null || describes.isEmpty() || describes[0] == null) {
                throw new SearchException('Object does not exist: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDescribe = describes[0];
            if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
                throw new SearchException('Running user does not have read access to object: ' + objDescribe.getName());
            }

            Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

            // Validate and collect SELECT fields (always include Id)
            Set<String> canonicalSelectFields = new Set<String>{ 'Id' };
            for (String fieldName : fields) {
                Schema.DescribeFieldResult dfr = resolveAndCheckReadableField(fieldMap, fieldName);
                canonicalSelectFields.add(dfr.getName());
            }

            // Validate filters and build WHERE clause with bind variables
            Map<String, Object> bindMap = new Map<String, Object>();
            List<String> whereClauses = new List<String>();

            if (filters != null && !filters.isEmpty()) {
                Integer bindIndex = 0;
                for (String filterField : filters.keySet()) {
                    Schema.DescribeFieldResult dfr = resolveAndCheckReadableField(fieldMap, filterField);
                    if (!dfr.isFilterable()) {
                        throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                    }

                    String bindVarName = 'filterVal_' + bindIndex++;
                    Object rawVal = filters.get(filterField);
                    bindMap.put(bindVarName, coerceBindValue(dfr, rawVal));
                    whereClauses.add(dfr.getName() + ' = :' + bindVarName);
                }
            }

            // Validate ORDER BY field
            String canonicalOrderByField = null;
            if (String.isNotBlank(orderByField)) {
                Schema.DescribeFieldResult dfr = resolveAndCheckReadableField(fieldMap, orderByField);
                if (!dfr.isSortable()) {
                    throw new SearchException('Field cannot be sorted: ' + dfr.getName());
                }
                canonicalOrderByField = dfr.getName();
            }

            // Construct SOQL query using canonical schema names and bind variables
            String soql = 'SELECT ' + String.join(new List<String>(canonicalSelectFields), ', ') +
                          ' FROM ' + objDescribe.getName();

            if (!whereClauses.isEmpty()) {
                soql += ' WHERE ' + String.join(whereClauses, ' AND ');
            }

            if (canonicalOrderByField != null) {
                soql += ' ORDER BY ' + canonicalOrderByField + ' ASC';
            }

            bindMap.put('maxRowsBind', maxRows);
            soql += ' LIMIT :maxRowsBind';

            return Database.queryWithBinds(soql, bindMap, AccessLevel.USER_MODE);
        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage(), e);
        }
    }

    private static Schema.DescribeFieldResult resolveAndCheckReadableField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('Field name cannot be blank.');
        }

        Schema.SObjectField sField = fieldMap.get(fieldName.trim());
        if (sField == null) {
            throw new SearchException('Field does not exist on object: ' + fieldName);
        }

        Schema.DescribeFieldResult dfr = sField.getDescribe();
        if (!dfr.isAccessible()) {
            throw new SearchException('Running user does not have read access to field: ' + dfr.getName());
        }

        return dfr;
    }

    private static Object coerceBindValue(Schema.DescribeFieldResult dfr, Object rawVal) {
        if (rawVal == null) {
            return null;
        }
        Schema.DisplayType dt = dfr.getType();
        if (rawVal instanceof String) {
            String strVal = (String) rawVal;
            if (dt == Schema.DisplayType.BOOLEAN) {
                if (strVal.equalsIgnoreCase('true')) {
                    return true;
                }
                if (strVal.equalsIgnoreCase('false')) {
                    return false;
                }
                throw new SearchException('Invalid boolean value for field ' + dfr.getName());
            } else if (dt == Schema.DisplayType.DATE) {
                return Date.valueOf(strVal);
            } else if (dt == Schema.DisplayType.DATETIME) {
                return Datetime.valueOf(strVal);
            } else if (dt == Schema.DisplayType.INTEGER) {
                return Integer.valueOf(strVal);
            } else if (
                dt == Schema.DisplayType.DOUBLE ||
                dt == Schema.DisplayType.CURRENCY ||
                dt == Schema.DisplayType.PERCENT
            ) {
                return Decimal.valueOf(strVal);
            }
        }
        return rawVal;
    }
}
