public with sharing class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body cannot be null or blank.');
        }

        Object raw;
        try {
            raw = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON payload.', e);
        }

        if (!(raw instanceof Map<String, Object>)) {
            throw new PayloadException('Payload root must be a JSON object.');
        }

        try {
            Map<String, Object> root = (Map<String, Object>) raw;
            Order result = new Order();

            Object numObj = root.get('number');
            if (!(numObj instanceof String) || String.isBlank((String) numObj)) {
                throw new PayloadException('Order number is required and cannot be blank.');
            }
            result.orderNumber = (String) numObj;

            Object dateObj = root.get('date');
            if (dateObj != null) {
                if (!(dateObj instanceof String)) {
                    throw new PayloadException('Invalid date format.');
                }
                String dateStr = (String) dateObj;
                if (String.isNotBlank(dateStr)) {
                    result.orderDate = parseIsoDate(dateStr);
                }
            }

            Object currObj = root.get('currency');
            if (currObj != null) {
                if (!(currObj instanceof String)) {
                    throw new PayloadException('Invalid currency format.');
                }
                result.currencyCode = (String) currObj;
            }

            Object custObj = root.get('customer');
            if (custObj != null) {
                if (!(custObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Customer must be a JSON object.');
                }
                Map<String, Object> custMap = (Map<String, Object>) custObj;
                Object emailObj = custMap.get('email');
                if (emailObj != null) {
                    if (!(emailObj instanceof String)) {
                        throw new PayloadException('Customer email must be a string.');
                    }
                    result.customerEmail = (String) emailObj;
                }
            }

            result.lines = new List<Line>();
            result.total = 0;

            Object linesObj = root.get('lines');
            if (linesObj != null) {
                if (!(linesObj instanceof List<Object>)) {
                    throw new PayloadException('Lines must be a JSON array.');
                }
                List<Object> rawLines = (List<Object>) linesObj;
                for (Object item : rawLines) {
                    if (!(item instanceof Map<String, Object>)) {
                        throw new PayloadException('Each line must be a JSON object.');
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) item;
                    Line line = new Line();

                    Object skuObj = lineMap.get('sku');
                    if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                        throw new PayloadException('Line sku is required and cannot be blank.');
                    }
                    line.sku = (String) skuObj;

                    Object qtyObj = lineMap.get('quantity');
                    line.quantity = toInteger(qtyObj, 'quantity');
                    if (line.quantity == null || line.quantity <= 0) {
                        throw new PayloadException('Line quantity must be a positive integer.');
                    }

                    Object priceObj = lineMap.get('unitPrice');
                    line.unitPrice = toDecimal(priceObj, 'unitPrice');
                    if (line.unitPrice == null || line.unitPrice < 0) {
                        throw new PayloadException('Line unitPrice is required and cannot be negative.');
                    }

                    Object discObj = lineMap.get('discount');
                    if (discObj == null) {
                        line.discount = 0;
                    } else {
                        line.discount = toDecimal(discObj, 'discount');
                        if (line.discount < 0 || line.discount > 1) {
                            throw new PayloadException('Line discount must be between 0 and 1.');
                        }
                    }

                    Decimal rawLineTotal = Decimal.valueOf(line.quantity) * line.unitPrice * (1 - line.discount);
                    line.lineTotal = rawLineTotal.setScale(2, System.RoundingMode.HALF_UP);

                    result.lines.add(line);
                    result.total += line.lineTotal;
                }
            }

            return result;
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Error parsing order payload: ' + e.getMessage(), e);
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order cannot be null.');
        }

        Integer lineCount = (order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order.total == null) ? 0 : order.total;

        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => lineCount,
            'total' => total
        };

        return JSON.serialize(ack);
    }

    private static Date parseIsoDate(String dateStr) {
        List<String> parts = dateStr.split('-');
        if (parts.size() != 3) {
            throw new PayloadException('Date must be in ISO format yyyy-MM-dd.');
        }
        Integer year = Integer.valueOf(parts[0]);
        Integer month = Integer.valueOf(parts[1]);
        Integer day = Integer.valueOf(parts[2]);
        Date parsed = Date.newInstance(year, month, day);
        if (parsed.year() != year || parsed.month() != month || parsed.day() != day) {
            throw new PayloadException('Invalid calendar date: ' + dateStr);
        }
        return parsed;
    }

    private static Integer toInteger(Object val, String fieldName) {
        if (val == null) {
            return null;
        }
        if (val instanceof Integer) {
            return (Integer) val;
        }
        if (val instanceof Long) {
            return ((Long) val).intValue();
        }
        if (val instanceof Decimal) {
            Decimal d = (Decimal) val;
            if (d.scale() > 0 && d.stripTrailingZeros().scale() > 0) {
                throw new PayloadException('Field ' + fieldName + ' must be an integer.');
            }
            return d.intValue();
        }
        throw new PayloadException('Field ' + fieldName + ' must be a number.');
    }

    private static Decimal toDecimal(Object val, String fieldName) {
        if (val == null) {
            return null;
        }
        if (val instanceof Decimal) {
            return (Decimal) val;
        }
        if (val instanceof Integer) {
            return Decimal.valueOf((Integer) val);
        }
        if (val instanceof Long) {
            return Decimal.valueOf((Long) val);
        }
        if (val instanceof Double) {
            return Decimal.valueOf((Double) val);
        }
        throw new PayloadException('Field ' + fieldName + ' must be a number.');
    }
}
