        Assert.areEqual(18.75, ShippingCostCalculator.quote(21.0, 'DOMESTIC', false, 0));
        Assert.areEqual(19.50, ShippingCostCalculator.quote(21.01, 'DOMESTIC', false, 0));
        Assert.areEqual(19.50, ShippingCostCalculator.quote(22.0, 'DOMESTIC', false, 0));
