        Assert.areEqual(5.00, ShippingCostCalculator.quote(1, 'DOMESTIC', null, null));

        // Negative orderValue -> not free
        Assert.areEqual(5.00, ShippingCostCalculator.quote(1, 'DOMESTIC', false, -100));

        // DOMESTIC express with orderValue >= 100 -> NOT free
        Assert.areEqual(7.50, ShippingCostCalculator.quote(1, 'DOMESTIC', true, 100.00));
        Assert.areEqual(7.50, ShippingCostCalculator.quote(1, 'DOMESTIC', true, 250.00));

        // Non-DOMESTIC standard with orderValue >= 100 -> NOT free
        Assert.areEqual(7.00, ShippingCostCalculator.quote(1, 'EU', false, 100.00));
        Assert.areEqual(7.00, ShippingCostCalculator.quote(1, 'EU', null, 200.00));
        Assert.areEqual(11.00, ShippingCostCalculator.quote(1, 'WORLD', false, 100.00));
