        // 21 kg DOMESTIC express:
        // base = 18.00 + 0.75 * 1 = 18.75
        // price = 18.75 * 1.0 * 1.5 = 28.125 -> HALF_UP to 2 decimals = 28.13
        // (HALF_EVEN, HALF_DOWN, FLOOR, DOWN would give 28.12)
        Decimal quote21DomExpress = ShippingCostCalculator.quote(21, 'DOMESTIC', true, 50);
        Assert.areEqual(28.13, quote21DomExpress);
