public with sharing class ErpSyncFinalizer implements Finalizer {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds != null ? new Set<Id>(accountIds) : new Set<Id>();
        this.attempt = attempt != null ? attempt : 1;
    }

    public void execute(FinalizerContext context) {
        FB_Job_Log__c logRecord = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c = this.attempt
        );

        ParentJobResult result = context != null ? context.getResult() : null;

        if (result == ParentJobResult.SUCCESS) {
            logRecord.Status__c = 'Success';
            insert logRecord;
        } else {
            logRecord.Status__c = 'Failed';
            Exception ex = context != null ? context.getException() : null;
            if (ex != null && ex.getMessage() != null) {
                logRecord.Error__c = ex.getMessage().left(255);
            }
            insert logRecord;

            if (this.attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(this.accountIds, this.attempt + 1));
            }
        }
    }
}
