public without sharing class OpportunityPipelineHandler {
    private static Boolean isUpdatingAccounts = false;

    public static void handleAfterTrigger(
        System.TriggerOperation operationType,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap
    ) {
        if (isUpdatingAccounts) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();

        switch on operationType {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity opp : newList) {
                    if (opp.AccountId != null && !opp.IsClosed) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
            when AFTER_DELETE {
                for (Opportunity opp : oldMap.values()) {
                    if (opp.AccountId != null && !opp.IsClosed) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
            when AFTER_UPDATE {
                for (Opportunity newOpp : newList) {
                    Opportunity oldOpp = oldMap.get(newOpp.Id);
                    Boolean accountChanged = newOpp.AccountId != oldOpp.AccountId;
                    Boolean closedChanged = newOpp.IsClosed != oldOpp.IsClosed;
                    Boolean amountChanged = newOpp.Amount != oldOpp.Amount;

                    if (accountChanged) {
                        if (oldOpp.AccountId != null && !oldOpp.IsClosed) {
                            accountIds.add(oldOpp.AccountId);
                        }
                        if (newOpp.AccountId != null && !newOpp.IsClosed) {
                            accountIds.add(newOpp.AccountId);
                        }
                    } else if (newOpp.AccountId != null) {
                        if (closedChanged || (!newOpp.IsClosed && amountChanged)) {
                            accountIds.add(newOpp.AccountId);
                        }
                    }
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recalculateAccounts(accountIds);
        }
    }

    public static void recalculateAccounts(Set<Id> accountIds) {
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            if (accId != null) {
                accountsToUpdate.put(
                    accId,
                    new Account(
                        Id = accId,
                        FB_Open_Pipeline__c = 0,
                        FB_Open_Opportunities__c = 0
                    )
                );
            }
        }

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        for (AggregateResult ar : [
            SELECT AccountId accId, COUNT(Id) openCount, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountsToUpdate.keySet() AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('accId');
            Integer openCount = (Integer) ar.get('openCount');
            Decimal totalAmount = (Decimal) ar.get('totalAmount');

            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Opportunities__c = openCount != null ? openCount : 0;
                acc.FB_Open_Pipeline__c = totalAmount != null ? totalAmount : 0;
            }
        }

        isUpdatingAccounts = true;
        try {
            update accountsToUpdate.values();
        } finally {
            isUpdatingAccounts = false;
        }
    }
}
