public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {
    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String NIGHTLY_CRON = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        purgeNow();
    }

    public static void purgeNow() {
        Datetime standardCutoff = System.now().addDays(-30);
        Datetime errorCutoff = System.now().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :standardCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
            LIMIT 10000
        ];

        if (!logsToDelete.isEmpty()) {
            Database.delete(logsToDelete, false);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime standardCutoff = System.now().addDays(-30);
        Datetime errorCutoff = System.now().addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :standardCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (scope != null && !scope.isEmpty()) {
            Database.delete(scope, false);
        }
    }

    public void finish(Database.BatchableContext bc) {
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }
}
