public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> totalsByAccountId = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return totalsByAccountId;
        }

        Set<Id> validAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                totalsByAccountId.put(accountId, 0);
                validAccountIds.add(accountId);
            }
        }

        if (validAccountIds.isEmpty()) {
            return totalsByAccountId;
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalWonAmount
            FROM Opportunity
            WHERE AccountId IN :validAccountIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal sumAmount = (Decimal) ar.get('totalWonAmount');
            totalsByAccountId.put(accId, sumAmount != null ? sumAmount : 0);
        }

        return totalsByAccountId;
    }
}
