@IsTest
private class OpportunityForecastServiceTest {
    @IsTest
    private static void weightedAmountByStageSumsRoundedWeightedAmountsPerStage() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        Id accountId1 = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountId2 = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId1, accountId2 };

        List<Opportunity> mockOpportunities = new List<Opportunity>{
            // 100.00 * 25 / 100 = 25.00
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId1,
                StageName = 'Prospecting',
                Amount = 100.00,
                Probability = 25
            ),
            // 33.33 * 33.33 / 100 = 11.108889 -> rounded to 2 decimals per opp = 11.11
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId1,
                StageName = 'Prospecting',
                Amount = 33.33,
                Probability = 33.33
            ),
            // Another 33.33 * 33.33 / 100 = 11.108889 -> rounded per opp = 11.11
            // (If rounded after summing, 11.108889 + 11.108889 = 22.217778 -> 22.22 + 25.00 = 47.22;
            //  when rounded per opp, 25.00 + 11.11 + 11.11 = 47.22; add a third to differentiate:
            //  3 * 11.104 = 33.312 -> 33.31 vs 3 * 11.10 = 33.30)
            // 100.04 * 11.1 / 100 = 11.10444 -> 11.10
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId2,
                StageName = 'Qualification',
                Amount = 100.04,
                Probability = 11.1
            ),
            // 100.04 * 11.1 / 100 = 11.10444 -> 11.10
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId2,
                StageName = 'Qualification',
                Amount = 100.04,
                Probability = 11.1
            ),
            // 100.04 * 11.1 / 100 = 11.10444 -> 11.10 (sum of 3 rounded = 33.30; unrounded sum = 33.31332 -> 33.31)
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId2,
                StageName = 'Qualification',
                Amount = 100.04,
                Probability = 11.1
            ),
            // 250.00 * 80 / 100 = 200.00
            new Opportunity(
                Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId = accountId2,
                StageName = 'Negotiation/Review',
                Amount = 250.00,
                Probability = 80
            )
        };

        mocks.startStubbing();
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(mockOpportunities);
        mocks.stopStubbing();

        Application.Selector.setMock(selectorMock);

        Test.startTest();
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);
        Test.stopTest();

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectOpenByAccountIds(accountIds);
        Assert.areEqual(0, Limits.getQueries(), 'No SOQL queries should be executed');
        Assert.areEqual(0, Limits.getDmlStatements(), 'No DML statements should be executed');
        Assert.areEqual(3, result.size(), 'Should contain totals for 3 distinct stages');
        Assert.areEqual(36.11, result.get('Prospecting'), 'Prospecting weighted total should be 25.00 + 11.11');
        Assert.areEqual(33.30, result.get('Qualification'), 'Qualification weighted total should be rounded per opportunity (3 * 11.10)');
        Assert.areEqual(200.00, result.get('Negotiation/Review'), 'Negotiation/Review weighted total should be 200.00');
    }

