public inherited sharing class Opportunities extends fflib_SObjectDomain {
    public static final String STAGE_CLOSED_WON = 'Closed Won';
    public static final String ERR_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    public static final String ERR_WON_AMOUNT_CHANGED = 'Amount cannot change on a won opportunity.';

    public Opportunities(List<Opportunity> sObjectList) {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    public override void onValidate() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            validateNonNegativeAmount(opp);
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        for (Opportunity opp : (List<Opportunity>) Records) {
            validateNonNegativeAmount(opp);

            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            if (oldOpp != null && oldOpp.StageName == STAGE_CLOSED_WON && opp.Amount != oldOpp.Amount) {
                opp.addError(
                    Opportunity.Amount,
                    error(ERR_WON_AMOUNT_CHANGED, opp, Opportunity.Amount)
                );
            }
        }
    }

    private void validateNonNegativeAmount(Opportunity opp) {
        if (opp.Amount != null && opp.Amount < 0) {
            opp.addError(
                Opportunity.Amount,
                error(ERR_NEGATIVE_AMOUNT, opp, Opportunity.Amount)
            );
        }
    }
}
