public with sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> createdAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return createdAccounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Contact> contactsToRegister = new List<Contact>();
        List<Account> parentAccountsForContacts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acct = new Account(Name = accountName);
            createdAccounts.add(acct);

            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);
            if (contactLastNames != null) {
                for (String lastName : contactLastNames) {
                    contactsToRegister.add(new Contact(LastName = lastName));
                    parentAccountsForContacts.add(acct);
                }
            }
        }

        uow.registerNew(createdAccounts);

        for (Integer i = 0; i < contactsToRegister.size(); i++) {
            uow.registerNew(contactsToRegister[i], Contact.AccountId, parentAccountsForContacts[i]);
        }

        uow.commitWork();

        return createdAccounts;
    }
}
