public with sharing class PipelineSummary {
    private static final List<String> TRACKED_STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : TRACKED_STAGES) {
            totals.put(stage, 0);
        }

        if (fromDate == null || toDate == null || fromDate > toDate) {
            return totals;
        }

        for (AggregateResult ar : [
            SELECT StageName stage, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE StageName IN :TRACKED_STAGES
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
             WITH USER_MODE
            GROUP BY StageName
        ]) {
            String stage = (String) ar.get('stage');
            Decimal sumAmount = (Decimal) ar.get('totalAmount');
            totals.put(stage, sumAmount != null ? sumAmount : 0);
        }

        return totals;
    }
}
