```apex
public with sharing class StaleOpportunityCloser {
    private static final String CLOSED_LOST_STAGE = 'Closed Lost';

    /**
     * Closes open opportunities whose CloseDate is strictly before the given cutoff date.
     *
     * Note: Performing DML outside the SOQL loop is used here instead of inside the loop
     * to avoid the "DML inside a loop" anti-pattern, conserve the 150 DML statement limit,
     * and prevent repetitive trigger/flow execution per 200-record chunk.
     * For volumes approaching or exceeding a few thousand records in production, a
     * Database.Batchable implementation launched by the Schedulable is strongly recommended
     * to avoid the 10,000 DML row limit and 10,000ms synchronous CPU limit.
     *
     * @param cutoff The date before which open opportunities are considered stale.
     * @return The number of opportunities updated to 'Closed Lost'.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer availableDmlRows = Limits.getLimitDmlRows() - Limits.getDmlRows();
        if (availableDmlRows <= 0) {
            return 0;
        }

        List<Opportunity> opportunitiesToUpdate = new List<Opportunity>();

        for (List<Opportunity> chunk : [
            SELECT Id
            FROM Opportunity
            WHERE IsClosed = FALSE AND CloseDate < :cutoff
            WITH USER_MODE
            LIMIT :availableDmlRows
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = CLOSED_LOST_STAGE;
                opportunitiesToUpdate.add(opp);
            }
        }

        if (!opportunitiesToUpdate.isEmpty()) {
            Database.update(opportunitiesToUpdate, AccessLevel.USER_MODE);
        }

        return opportunitiesToUpdate.size();
    }
}
