public inherited sharing class AccountCountrySync {

    /**
     * Synchronizes Contact.MailingCountry when an Account's BillingCountry changes.
     * Updates contacts whose MailingCountry is blank or matches the Account's previous BillingCountry.
     *
     * @param newAccounts List of updated Account records (Trigger.new)
     * @param oldAccountMap Map of prior Account records by Id (Trigger.oldMap)
     */
    public static void syncContactMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        if (newAccounts == null || newAccounts.isEmpty() || oldAccountMap == null) {
            return;
        }

        // Collect only the Accounts where BillingCountry actually changed
        Map<Id, Account> changedAccountsById = new Map<Id, Account>();
        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (oldAcc != null && acc.BillingCountry != oldAcc.BillingCountry) {
                changedAccountsById.put(acc.Id, acc);
            }
        }

        // Exit early before consuming any SOQL if no relevant changes occurred
        if (changedAccountsById.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Selective query using the indexed AccountId field in a SOQL for-loop to minimize heap usage
        for (Contact con : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountsById.keySet()
        ]) {
            Account newAcc = changedAccountsById.get(con.AccountId);
            Account oldAcc = oldAccountMap.get(con.AccountId);

            String oldBillingCountry = oldAcc.BillingCountry;
            String newBillingCountry = newAcc.BillingCountry;

            Boolean isMailingBlank = String.isBlank(con.MailingCountry);
            Boolean matchesPreviousCountry = !isMailingBlank
                && String.isNotBlank(oldBillingCountry)
                && con.MailingCountry.equalsIgnoreCase(oldBillingCountry);

            if (isMailingBlank || matchesPreviousCountry) {
                // Only add to DML list if the value will actually change
                if (con.MailingCountry != newBillingCountry) {
                    con.MailingCountry = newBillingCountry;
                    contactsToUpdate.add(con);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
