import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleInputChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail ? event.detail.value : event.target.value;
        if (field) {
            this[field] = value;
        }
    }

    async handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        if (emailInput) {
            const emailVal = (this.email || '').trim();
            const atIndex = emailVal.lastIndexOf('@');
            const domain = atIndex !== -1 ? emailVal.slice(atIndex + 1).toLowerCase() : '';

            if (PERSONAL_DOMAINS.has(domain)) {
                emailInput.setCustomValidity('Use your work email address.');
            } else {
                emailInput.setCustomValidity('');
            }
        }

        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const allValid = inputs.reduce((validSoFar, inputCmp) => {
            const isValid = inputCmp.reportValidity();
            return validSoFar && isValid;
        }, true);

        if (!allValid) {
            return;
        }

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message: error?.body?.message,
                    variant: 'error'
                })
            );
        }
    }
}
