import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    _activeIndex = -1;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this.syncActiveIndexToValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveIndexToValue();
    }

    syncActiveIndexToValue() {
        if (!this._options || this._options.length === 0) {
            this._activeIndex = -1;
            return;
        }
        const selectedIndex = this._options.findIndex((opt) => opt.value === this._value);
        if (selectedIndex >= 0) {
            this._activeIndex = selectedIndex;
        } else if (this._activeIndex < 0 || this._activeIndex >= this._options.length) {
            this._activeIndex = 0;
        }
    }

    get computedOptions() {
        return this._options.map((opt, index) => {
            const isSelected = opt.value === this._value;
            const isActive = index === this._activeIndex;
            return {
                value: opt.value,
                label: opt.label,
                id: `option-${index}`,
                ariaSelected: isSelected ? 'true' : 'false',
                className: `slds-media slds-listbox__option slds-listbox__option_plain slds-media_small${isSelected ? ' slds-is-selected' : ''}${isActive ? ' slds-has-focus' : ''}`
            };
        });
    }

    get activeDescendantId() {
        const opts = this.computedOptions;
        if (this._activeIndex >= 0 && this._activeIndex < opts.length) {
            return opts[this._activeIndex].id;
        }
        return undefined;
    }

    renderedCallback() {
        const listbox = this.template.querySelector('[role="listbox"]');
        if (!listbox) {
            return;
        }
        const optionEls = this.template.querySelectorAll('[role="option"]');
        if (this._activeIndex >= 0 && this._activeIndex < optionEls.length) {
            const activeEl = optionEls[this._activeIndex];
            if (activeEl && activeEl.id) {
                listbox.setAttribute('aria-activedescendant', activeEl.id);
            }
        } else {
            listbox.removeAttribute('aria-activedescendant');
        }
    }

    handleKeyDown(event) {
        const len = this._options.length;
        const { key } = event;

        switch (key) {
            case 'ArrowDown':
                event.preventDefault();
                if (len > 0 && this._activeIndex < len - 1) {
                    this._activeIndex += 1;
                }
                break;
            case 'ArrowUp':
                event.preventDefault();
                if (len > 0 && this._activeIndex > 0) {
                    this._activeIndex -= 1;
                }
                break;
            case 'Home':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = 0;
                }
                break;
            case 'End':
                event.preventDefault();
                if (len > 0) {
                    this._activeIndex = len - 1;
                }
                break;
            case 'Enter':
            case ' ':
                event.preventDefault();
                if (this._activeIndex >= 0 && this._activeIndex < len) {
                    this.selectOptionAtIndex(this._activeIndex);
                }
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex((opt) => String(opt.value) === clickedValue);
        if (index >= 0) {
            this._activeIndex = index;
            this.selectOptionAtIndex(index);
        }
    }

    selectOptionAtIndex(index) {
        const option = this._options[index];
        if (!option) {
            return;
        }
        const newValue = option.value;
        if (newValue === this._value) {
            return;
        }
        this._value = newValue;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: newValue }
            })
        );
    }
}
