public with sharing class EmployerService {

    /**
     * Sets the current primary employer (Organization Account) for each given Contact.
     *
     * Leverages NPSP's AFFL_Affiliations_TDTM trigger on Contact: when Contact.npsp__Primary_Affiliation__c
     * changes, NPSP automatically creates a new Current, Primary npe5__Affiliation__c record for the new
     * organization and demotes the previous primary affiliation to Former (non-primary, with End Date = today),
     * while leaving the Contact's AccountId (Household Account) intact.
     *
     * @param employerByContactId Map of Contact Id to Organization Account Id
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());
        contactIds.remove(null);
        if (contactIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            Id newEmployerId = employerByContactId.get(c.Id);
            if (c.npsp__Primary_Affiliation__c != newEmployerId) {
                contactsToUpdate.add(new Contact(
                    Id = c.Id,
                    npsp__Primary_Affiliation__c = newEmployerId
                ));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
