public with sharing class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('GAU percentage map cannot be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id cannot be null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('All allocation percentages must be greater than 0.');
            }
            totalPercent += pct;
        }

        if (totalPercent > 100) {
            throw new AllocationException('Total allocation percentage cannot exceed 100%.');
        }

        Map<Id, npsp__General_Accounting_Unit__c> gausById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gausById.get(gauId);
            if (gau == null || gau.npsp__Active__c != true) {
                throw new AllocationException('All General Accounting Units must exist and be active.');
            }
        }

        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }

        // In NPSP, populating npsp__Percent__c (and leaving npsp__Amount__c null so NPSP calculates it)
        // ensures NPSP automatically recalculates the allocation amounts whenever the Opportunity Amount changes.
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(
                new npsp__Allocation__c(
                    npsp__Opportunity__c = opportunityId,
                    npsp__General_Accounting_Unit__c = gauId,
                    npsp__Percent__c = percentByGauId.get(gauId)
                )
            );
        }

        insert newAllocations;

        Map<Id, npsp__Allocation__c> refreshedById = new Map<Id, npsp__Allocation__c>(
            [
                SELECT
                    Id,
                    npsp__Opportunity__c,
                    npsp__General_Accounting_Unit__c,
                    npsp__Amount__c,
                    npsp__Percent__c,
                    npsp__Payment__c,
                    npsp__Campaign__c,
                    npsp__Recurring_Donation__c
                FROM npsp__Allocation__c
                WHERE Id IN :newAllocations
            ]
        );

        List<npsp__Allocation__c> orderedResult = new List<npsp__Allocation__c>();
        for (npsp__Allocation__c alloc : newAllocations) {
            npsp__Allocation__c refreshed = refreshedById.get(alloc.Id);
            orderedResult.add(refreshed != null ? refreshed : alloc);
        }

        return orderedResult;
    }
}
