public with sharing class HouseholdService {

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('Members list cannot be null or empty.');
        }

        // Insert the first contact without an AccountId so NPSP's Household Account model
        // automatically creates a single Household Account (with HH_Account record type),
        // sets npe01__One2OneContact__c to this contact, and runs automatic household naming.
        Contact primaryContact = members[0];
        insert primaryContact;

        // Query back the AccountId that NPSP generated for the primary contact
        Id householdAccountId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primaryContact.Id
            LIMIT 1
        ].AccountId;

        // If for any reason NPSP triggers didn't create the Household Account (e.g. disabled in tests),
        // create the Household Account explicitly using the HH_Account RecordType.
        if (householdAccountId == null) {
            Id hhRecordTypeId = Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
                .get('HH_Account')
                .getRecordTypeId();

            Account hhAccount = new Account(
                Name = 'Anonymous Household',
                RecordTypeId = hhRecordTypeId,
                npe01__One2OneContact__c = primaryContact.Id,
                npe01__SYSTEM_AccountType__c = 'Household Account',
                npe01__SYSTEMIsIndividual__c = true
            );
            insert hhAccount;
            householdAccountId = hhAccount.Id;

            primaryContact.AccountId = householdAccountId;
            update primaryContact;
        } else {
            // Keep the in-memory reference updated with the generated AccountId
            primaryContact.AccountId = householdAccountId;
        }

        // Assign the remaining family members to the newly created Household Account and insert them.
        // Because AccountId is populated, NPSP will not create extra Household Accounts for them,
        // and will automatically recalculate household naming and greetings to include all members.
        if (members.size() > 1) {
            List<Contact> additionalMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i];
                member.AccountId = householdAccountId;
                additionalMembers.add(member);
            }
            insert additionalMembers;
        }

        return householdAccountId;
    }
}
