public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();

        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Request must specify both opportunityId and contactId.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be positive.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Soft credit role must be specified.');
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // SOQL 1: Query Opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c != null && opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Cannot assign partial soft credit to the primary contact of the opportunity.');
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException('Soft credit amount cannot exceed the opportunity amount.');
            }
        }

        // SOQL 2: Query existing Partial Soft Credits (and any associated OCRs created automatically or previously)
        Map<String, List<npsp__Partial_Soft_Credit__c>> existingPscsByPair = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = getPairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!existingPscsByPair.containsKey(key)) {
                existingPscsByPair.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            existingPscsByPair.get(key).add(psc);
        }

        // SOQL 3: Query existing OpportunityContactRoles
        Map<String, List<OpportunityContactRole>> existingOcrsByPair = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId IN :contactIds
            ORDER BY IsPrimary DESC, CreatedDate ASC, Id ASC
        ]) {
            String key = getPairKey(ocr.OpportunityId, ocr.ContactId);
            if (!existingOcrsByPair.containsKey(key)) {
                existingOcrsByPair.put(key, new List<OpportunityContactRole>());
            }
            existingOcrsByPair.get(key).add(ocr);
        }

        Map<Id, OpportunityContactRole> ocrsToDeleteMap = new Map<Id, OpportunityContactRole>();
        Map<Id, npsp__Partial_Soft_Credit__c> pscsToDeleteMap = new Map<Id, npsp__Partial_Soft_Credit__c>();
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> targetOcrByPair = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = getPairKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> ocrs = existingOcrsByPair.get(key);
            List<npsp__Partial_Soft_Credit__c> pscs = existingPscsByPair.get(key);

            npsp__Partial_Soft_Credit__c targetPsc = null;
            if (pscs != null && !pscs.isEmpty()) {
                targetPsc = pscs[0];
                for (Integer i = 1; i < pscs.size(); i++) {
                    pscsToDeleteMap.put(pscs[i].Id, pscs[i]);
                }
            }

            OpportunityContactRole targetOcr = null;
            if (ocrs != null && !ocrs.isEmpty()) {
                // Prefer the OCR already linked to the existing PSC if present
                if (targetPsc != null && String.isNotBlank(targetPsc.npsp__Contact_Role_ID__c)) {
                    for (OpportunityContactRole ocr : ocrs) {
                        if (String.valueOf(ocr.Id) == targetPsc.npsp__Contact_Role_ID__c ||
                            String.valueOf(ocr.Id).left(15) == targetPsc.npsp__Contact_Role_ID__c.left(15)) {
                            targetOcr = ocr;
                            break;
                        }
                    }
                }
                if (targetOcr == null) {
                    targetOcr = ocrs[0];
                }
                for (OpportunityContactRole ocr : ocrs) {
                    if (ocr.Id != targetOcr.Id) {
                        ocrsToDeleteMap.put(ocr.Id, ocr);
                    }
                }
                if (targetOcr.Role != req.role) {
                    targetOcr.Role = req.role;
                    ocrsToUpsert.add(targetOcr);
                }
            } else {
                targetOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role,
                    IsPrimary = false
                );
                ocrsToUpsert.add(targetOcr);
            }
            targetOcrByPair.put(key, targetOcr);
        }

        // DML 1: Upsert OpportunityContactRoles (inserts new ones so we get their Ids, and updates changed roles)
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        // Prepare PSCs for upsert
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        for (SoftCreditRequest req : requests) {
            String key = getPairKey(req.opportunityId, req.contactId);
            OpportunityContactRole targetOcr = targetOcrByPair.get(key);
            List<npsp__Partial_Soft_Credit__c> pscs = existingPscsByPair.get(key);

            if (pscs != null && !pscs.isEmpty()) {
                npsp__Partial_Soft_Credit__c existingPsc = pscs[0];
                if (existingPsc.npsp__Amount__c != req.amount ||
                    existingPsc.npsp__Role_Name__c != req.role ||
                    existingPsc.npsp__Contact_Role_ID__c != String.valueOf(targetOcr.Id)) {
                    existingPsc.npsp__Amount__c = req.amount;
                    existingPsc.npsp__Role_Name__c = req.role;
                    existingPsc.npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id);
                    pscsToUpsert.add(existingPsc);
                }
            } else {
                pscsToUpsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = String.valueOf(targetOcr.Id)
                ));
            }
        }

        // DML 2: Upsert Partial Soft Credits
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }

        // DML 3 & 4: Clean up any duplicate PSCs or duplicate OCRs if any existed
        if (!pscsToDeleteMap.isEmpty()) {
            delete pscsToDeleteMap.values();
        }
        if (!ocrsToDeleteMap.isEmpty()) {
            delete ocrsToDeleteMap.values();
        }
    }

    private static String getPairKey(Id oppId, Id contactId) {
        return String.valueOf(oppId) + '_' + String.valueOf(contactId);
    }
}
