public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id cannot be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }

        Contact donor = contacts[0];
        Date effectiveDate = (giftDate != null) ? giftDate : Date.today();

        // Format opportunity name: <FirstName> <LastName> Donation <yyyy-MM-dd>
        String fullName = String.isNotBlank(donor.FirstName)
            ? donor.FirstName.trim() + ' ' + donor.LastName.trim()
            : donor.LastName.trim();
        String dateString = Datetime.newInstance(
            effectiveDate.year(),
            effectiveDate.month(),
            effectiveDate.day()
        ).format('yyyy-MM-dd');
        String oppName = fullName + ' Donation ' + dateString;

        String closedWonStage = getClosedWonStageName();

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = effectiveDate,
            StageName = closedWonStage
        );
        insert opp;

        // Reconcile Opportunity Contact Roles (handles whether NPSP triggers ran or not)
        reconcileContactRoles(opp.Id, donor);

        // Reconcile NPSP Payment (handles whether NPSP triggers auto-created a payment or not)
        reconcilePayments(opp.Id, amount, effectiveDate);

        return opp.Id;
    }

    private static String getClosedWonStageName() {
        List<OpportunityStage> stages = [
            SELECT MasterLabel, ApiName
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder ASC
            LIMIT 1
        ];
        if (!stages.isEmpty()) {
            return stages[0].ApiName;
        }
        return 'Closed Won';
    }

    private static void reconcileContactRoles(Id oppId, Contact donor) {
        Set<Id> householdMemberIds = new Set<Id>();
        if (donor.AccountId != null) {
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :donor.AccountId
                AND Id != :donor.Id
            ]) {
                householdMemberIds.add(member.Id);
            }
        }

        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :oppId
        ];

        Map<Id, OpportunityContactRole> contactIdToOcr = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();

        for (OpportunityContactRole ocr : existingOcrs) {
            boolean isValidContact = (ocr.ContactId == donor.Id || householdMemberIds.contains(ocr.ContactId));
            if (!isValidContact || contactIdToOcr.containsKey(ocr.ContactId)) {
                ocrsToDelete.add(ocr);
            } else {
                contactIdToOcr.put(ocr.ContactId, ocr);
            }
        }

        // Ensure Primary Donor role
        if (contactIdToOcr.containsKey(donor.Id)) {
            OpportunityContactRole donorOcr = contactIdToOcr.get(donor.Id);
            if (donorOcr.Role != 'Donor' || !donorOcr.IsPrimary) {
                donorOcr.Role = 'Donor';
                donorOcr.IsPrimary = true;
                ocrsToUpsert.add(donorOcr);
            }
        } else {
            ocrsToUpsert.add(new OpportunityContactRole(
                OpportunityId = oppId,
                ContactId = donor.Id,
                Role = 'Donor',
                IsPrimary = true
            ));
        }

        // Ensure Household Member roles for all other household contacts
        for (Id memberId : householdMemberIds) {
            if (contactIdToOcr.containsKey(memberId)) {
                OpportunityContactRole memberOcr = contactIdToOcr.get(memberId);
                if (memberOcr.Role != 'Household Member' || memberOcr.IsPrimary) {
                    memberOcr.Role = 'Household Member';
                    memberOcr.IsPrimary = false;
                    ocrsToUpsert.add(memberOcr);
                }
            } else {
                ocrsToUpsert.add(new OpportunityContactRole(
                    OpportunityId = oppId,
                    ContactId = memberId,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }
    }

    private static void reconcilePayments(Id oppId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c, npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :oppId
            ORDER BY CreatedDate ASC
        ];

        if (existingPayments.isEmpty()) {
            insert new npe01__OppPayment__c(
                npe01__Opportunity__c = oppId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
        } else {
            npe01__OppPayment__c primaryPayment = existingPayments[0];
            if (
                primaryPayment.npe01__Payment_Amount__c != amount ||
                primaryPayment.npe01__Payment_Date__c != giftDate ||
                primaryPayment.npe01__Scheduled_Date__c != giftDate ||
                primaryPayment.npe01__Paid__c != true
            ) {
                primaryPayment.npe01__Payment_Amount__c = amount;
                primaryPayment.npe01__Payment_Date__c = giftDate;
                primaryPayment.npe01__Scheduled_Date__c = giftDate;
                primaryPayment.npe01__Paid__c = true;
                update primaryPayment;
            }

            if (existingPayments.size() > 1) {
                List<npe01__OppPayment__c> duplicatePayments = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < existingPayments.size(); i++) {
                    duplicatePayments.add(existingPayments[i]);
                }
                delete duplicatePayments;
            }
        }
    }
}
