public with sharing class RecordAccessService {
    private static final Integer MAX_IDS_PER_QUERY = 200;

    /**
     * Returns the subset of recordIds that the running user has edit access to,
     * based on the UserRecordAccess system object.
     *
     * Note: Queries against UserRecordAccess allow at most 200 RecordIds in the
     * IN-clause per SOQL query, so inputs are chunked into batches of 200.
     *
     * @param recordIds The set of record IDs to check.
     * @return A non-null Set<Id> of records the running user can edit.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableRecordIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableRecordIds;
        }

        Id currentUserId = UserInfo.getUserId();
        List<Id> batch = new List<Id>();

        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }
            batch.add(recordId);

            if (batch.size() == MAX_IDS_PER_QUERY) {
                collectEditableIds(currentUserId, batch, editableRecordIds);
                batch.clear();
            }
        }

        if (!batch.isEmpty()) {
            collectEditableIds(currentUserId, batch, editableRecordIds);
        }

        return editableRecordIds;
    }

    private static void collectEditableIds(
        Id userId,
        List<Id> recordIdBatch,
        Set<Id> editableRecordIds
    ) {
        for (UserRecordAccess access : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :userId
              AND RecordId IN :recordIdBatch
        ]) {
            if (access.HasEditAccess) {
                editableRecordIds.add(access.RecordId);
            }
        }
    }
}
