@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    @IsTest
    private static void shouldRejectReductionMoreThanHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 499);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isTrue(newOpp.hasErrors(), 'Expected an error when Amount is reduced by more than half.');
        Assert.areEqual(1, newOpp.getErrors().size(), 'Expected exactly one error on the record.');
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            newOpp.getErrors()[0].getMessage(),
            'Error message should match ERROR_MESSAGE constant.'
        );
    }

    @IsTest
    private static void shouldAllowReductionOfExactlyHalf() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'A reduction of exactly half should be allowed.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'Expected no errors on the record.');
    }

    @IsTest
    private static void shouldAllowAmountIncrease() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = 1000);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 1500);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'An increase in Amount should be allowed.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'Expected no errors on the record.');
    }

    @IsTest
    private static void shouldAllowWhenPreviousAmountWasNull() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldOpp = new Opportunity(Id = oppId, Amount = null);
        Opportunity newOpp = new Opportunity(Id = oppId, Amount = 250);

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newOpp },
            new List<Opportunity>{ oldOpp }
        );

        Assert.isFalse(newOpp.hasErrors(), 'A record with a null previous Amount should be allowed without error.');
        Assert.areEqual(0, newOpp.getErrors().size(), 'Expected no errors on the record.');
    }

    @IsTest
    private static void shouldEvaluateMultipleRecordsIndependently() {
        Id invalidOpp1Id = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validHalfOppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id invalidOpp2Id = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validIncreaseOppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id validNullPrevOppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldInvalid1 = new Opportunity(Id = invalidOpp1Id, Amount = 1000);
        Opportunity newInvalid1 = new Opportunity(Id = invalidOpp1Id, Amount = 499);

        Opportunity oldValidHalf = new Opportunity(Id = validHalfOppId, Amount = 1000);
        Opportunity newValidHalf = new Opportunity(Id = validHalfOppId, Amount = 500);

        Opportunity oldInvalid2 = new Opportunity(Id = invalidOpp2Id, Amount = 200);
        Opportunity newInvalid2 = new Opportunity(Id = invalidOpp2Id, Amount = 50);

        Opportunity oldValidIncrease = new Opportunity(Id = validIncreaseOppId, Amount = 500);
        Opportunity newValidIncrease = new Opportunity(Id = validIncreaseOppId, Amount = 800);

        Opportunity oldValidNullPrev = new Opportunity(Id = validNullPrevOppId, Amount = null);
        Opportunity newValidNullPrev = new Opportunity(Id = validNullPrevOppId, Amount = 100);

        List<Opportunity> triggerOld = new List<Opportunity>{
