public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<Contact> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }

        for (Contact con : triggerNew) {
            if (con.AccountId == null) {
                continue;
            }
            Account parentAccount = accountsById.get(con.AccountId);
            if (parentAccount == null) {
                continue;
            }
            if (
                String.isBlank(con.MailingStreet) &&
                String.isBlank(con.MailingCity) &&
                String.isBlank(con.MailingPostalCode) &&
                String.isBlank(con.MailingCountry)
            ) {
                con.MailingStreet = parentAccount.BillingStreet;
                con.MailingCity = parentAccount.BillingCity;
                con.MailingPostalCode = parentAccount.BillingPostalCode;
                con.MailingCountry = parentAccount.BillingCountry;
            }
        }
    }
}
