public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<Contact> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }

        for (Contact con : triggerNew) {
            if (con.AccountId == null || !String.isBlank(con.LeadSource)) {
                continue;
            }
            Account parentAccount = accountsById.get(con.AccountId);
            if (parentAccount != null && !String.isBlank(parentAccount.AccountSource)) {
                con.LeadSource = parentAccount.AccountSource;
            }
        }
    }
}
